820							ch.errCh <- errors.New("source has a 'chart' field defined, but Helm charts are not yet not supported for 'ref' sources")
821							return
822						}
823						normalizedRepoURL := git.NormalizeGitURL(refSourceMapping.Repo.Repo)
824						closer, ok := repoRefs[normalizedRepoURL]
825						if ok {
826							if closer.revision != refSourceMapping.TargetRevision {
827								ch.errCh <- fmt.Errorf("cannot reference multiple revisions for the same repository (%s references %q while %s references %q)", refVar, refSourceMapping.TargetRevision, closer.key, closer.revision)
828								return
