// checkoutReferencedValueFileSources resolves and checks out the external repositories that are
// referenced (using the $refname/path/to/file.yaml syntax) by the given value files. Only ref
// sources that are actually referenced are touched; ref sources declared in q.RefSources but not
// referenced by any value file are left alone (no git operations are performed for them).
//
// The returned closers must be closed by the caller once the referenced value files have been
// read, in order to release the repository locks that are held while the repos are checked out.
//
// Much of this logic is duplicated in runManifestGenAsync. If making changes here, check whether
// runManifestGenAsync should be updated.
func (s *Service) checkoutReferencedValueFileSources(valueFiles []string, sha string, targetRevision string, q *apiclient.RepoServerAppDetailsQuery, tempPaths utilio.TempPaths) ([]goio.Closer, error) {
	var closers []goio.Closer

	// Collect the ref names that are actually referenced by the value files.
	referenced := make(map[string]bool)
	for _, valueFile := range valueFiles {
		if !strings.HasPrefix(valueFile, "$") {
			continue
		}
		referenced[strings.Split(valueFile, "/")[0]] = true
	}
	if len(referenced) == 0 {
		return closers, nil
	}

	// Process the ref sources in lexicographically sorted order so that error messages are
	// deterministic: on a conflict, the name being processed (alphabetically later) is reported
	// first and the previously-seen conflicting name second.
	refNames := make([]string, 0, len(q.RefSources))
	for refName := range q.RefSources {
		refNames = append(refNames, refName)
	}
	sort.Strings(refNames)

	repoRefs := make(map[string]repoRef)
	for _, refName := range refNames {
		if !referenced[refName] {
			continue
		}
		refSourceMapping := q.RefSources[refName]
		normalizedRepoURL := git.NormalizeGitURL(refSourceMapping.Repo.Repo)

		// Non-git referenced repos (e.g. OCI) are already fetched to a cached path; we only need
		// to verify that a cached path exists for them, no checkout is required.
		if refSourceMapping.Repo.Type != "git" && refSourceMapping.Repo.Type != "" {
			tempPaths.GetPathIfExists(normalizedRepoURL)
			continue
		}

		gitClient, referencedCommitSHA, err := s.newClientResolveRevision(&refSourceMapping.Repo, refSourceMapping.TargetRevision, git.WithCache(s.cache, !q.NoRevisionCache && !q.NoCache))
		if err != nil {
			return closers, fmt.Errorf("error setting up git client for %s and resolving revision %s: %w", refSourceMapping.Repo.Repo, refSourceMapping.TargetRevision, err)
		}

		// The ref source points at the same repository as the main application, but resolves to a
		// different revision than the one the application is using.
		if git.NormalizeGitURL(q.Source.RepoURL) == normalizedRepoURL && sha != referencedCommitSHA {
			return closers, fmt.Errorf("cannot reference a different revision of the same repository (%s references %q which resolves to %q while the application references %q which resolves to %q)", refName, refSourceMapping.TargetRevision, referencedCommitSHA, targetRevision, sha)
		}

		// Two different ref sources point at the same external repository but resolve to different
		// revisions.
		if existing, ok := repoRefs[normalizedRepoURL]; ok {
			if existing.commitSHA != referencedCommitSHA {
				return closers, fmt.Errorf("cannot reference multiple revisions for the same repository (%s references %q which resolves to %q while %s references %q which resolves to %q)", refName, refSourceMapping.TargetRevision, referencedCommitSHA, existing.key, existing.revision, existing.commitSHA)
			}
			// Already checked out at the same revision under an earlier ref name.
			continue
		}

		closer, err := s.repoLock.Lock(gitClient.Root(), referencedCommitSHA, true, func(clean bool) (goio.Closer, error) {
			return s.checkoutRevision(gitClient, referencedCommitSHA, s.initConstants.SubmoduleEnabled, q.Repo.Depth, clean)
		})
		if err != nil {
			return closers, fmt.Errorf("failed to acquire lock for referenced repo %s: %w", refSourceMapping.Repo.Repo, err)
		}
		closers = append(closers, closer)

		repoRefs[normalizedRepoURL] = repoRef{revision: refSourceMapping.TargetRevision, commitSHA: referencedCommitSHA, key: refName}
	}

	return closers, nil
}

